a11y.vectorNode.tip.accessibleObjectResp.english:
{ $coordinateSnapMode ->
  [cartesian] { $tipReturnedToGraphArea ->
                [true] tip at { $tipX } { $tipY }, tip returned to graph area
                *[false] tip at { $tipX } { $tipY }
              }
  *[polar] { $tipReturnedToGraphArea ->
             [true] magnitude { $magnitude }, direction { $angle } degrees, tip returned to graph area
             *[false] magnitude { $magnitude }, direction { $angle } degrees
           }
}

a11y.vectorNode.tip.accessibleObjectResp.khmer:
{ $coordinateSnapMode ->
  [cartesian] { $tipReturnedToGraphArea ->
                [true] ចុងនៅ { $tipX } { $tipY }, ចុងបានត្រឡប់មកក្នុងផ្ទៃក្រាបវិញ
                *[false] ចុងនៅ { $tipX } { $tipY }
              }
  *[polar] { $tipReturnedToGraphArea ->
             [true] ម៉ូឌុល { $magnitude }, ទិសដៅ { $angle } ដឺក្រេ, ចុងបានត្រឡប់មកក្នុងផ្ទៃក្រាបវិញ
             *[false] ម៉ូឌុល { $magnitude }, ទិសដៅ { $angle } ដឺក្រេ
           }
}
